import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());long l = Long.parseLong(st.nextToken());long r = Long.parseLong(st.nextToken());long x = Long.parseLong(st.nextToken());int[] c = new int[n];st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {c[i] = Integer.parseInt(st.nextToken());}int count = 0;for (int i = 0; i < (1 << n); i++) {int setSize = 0;long sum = 0;int min = Integer.MAX_VALUE;int max = Integer.MIN_VALUE;for (int j = 0; j < n; j++) {if (((i >> j) & 1) == 1) {setSize++;sum += c[j];if (c[j] < min) min = c[j];if (c[j] > max) max = c[j];}}if (setSize >= 2 && sum >= l && sum <= r && (max - min) >= x) {count++;}}System.out.println(count);}}